import{_ as e,o as s,c as o,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Primeiros passos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/getting-started.md","filePath":"pt/getting-started.md"}'),i={name:"pt/getting-started.md"};function n(t,a,p,d,c,l){return s(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="primeiros-passos" tabindex="-1">Primeiros passos <a class="header-anchor" href="#primeiros-passos" aria-label="Permalink to &quot;Primeiros passos&quot;">​</a></h1><p>Esta página acompanha-o desde a compra até à primeira abertura do painel de definições no jogo. O processo é o mesmo para todos os scripts Nayretis.</p><h2 id="comprar-e-transferir" tabindex="-1">Comprar e transferir <a class="header-anchor" href="#comprar-e-transferir" aria-label="Permalink to &quot;Comprar e transferir&quot;">​</a></h2><ol><li>Compre o script na <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">loja Nayretis</a>. O pagamento é feito através do Tebex.</li><li>Inicie sessão no <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> com a conta Cfx.re usada na compra. O script e o <code>nay_lib</code> estão nos seus granted assets.</li><li>Transfira os dois. O <code>nay_lib</code> acompanha cada script Nayretis e nunca é vendido em separado.</li></ol><p>Os scripts estão protegidos pelo escrow da Cfx: só arrancam num servidor cuja license key pertence à conta Cfx.re que os possui.</p><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, iniciado e ligado à sua base de dados.</li><li>Um dos frameworks suportados: ESX Legacy, QBCore, QBox ou ox_core. Consulte <a href="/pt/bridge/">Bridge</a> para inventários, targets e notificações.</li></ul><h2 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h2><p>Copie a pasta <code>nay_lib</code> e a pasta do script para a sua pasta <code>resources</code>. No <code>server.cfg</code>, inicie-os depois dos recursos de framework, inventário e target:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># your framework, inventory and target resources here</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>O <code>nay_lib</code> é instalado uma única vez, seja qual for o número de scripts Nayretis que usa. Mantenha-o antes de todos os scripts Nayretis.</p><h2 id="primeiro-arranque" tabindex="-1">Primeiro arranque <a class="header-anchor" href="#primeiro-arranque" aria-label="Permalink to &quot;Primeiro arranque&quot;">​</a></h2><p>Inicie o servidor. As tabelas da base de dados são criadas automaticamente, não há nenhum ficheiro SQL para importar. Na consola deverá ver:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>Os nomes do framework e do inventário correspondem aos que o seu servidor usa.</p><h2 id="de-acesso-a-si-proprio" tabindex="-1">Dê acesso a si próprio <a class="header-anchor" href="#de-acesso-a-si-proprio" aria-label="Permalink to &quot;Dê acesso a si próprio&quot;">​</a></h2><p>As definições são editadas no jogo com <code>/nay</code>. Dê acesso total ao grupo admin no <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>Ou conceda-o a um único jogador a partir da consola do servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Depois entre no servidor e escreva <code>/nay</code>. Mais opções na página <a href="/pt/nay-lib/permissions">Permissões</a>.</p><h2 id="proximos-passos" tabindex="-1">Próximos passos <a class="header-anchor" href="#proximos-passos" aria-label="Permalink to &quot;Próximos passos&quot;">​</a></h2><ul><li>Conheça o <a href="/pt/nay-lib/panel">painel /nay</a>: idiomas, tema, permissões, API e webhooks.</li><li>Configure o <a href="/pt/car-wash/">Car Wash</a>.</li><li>Algo não arranca? Leia as <a href="/pt/faq">Perguntas frequentes</a>.</li></ul>`,23)])])}const m=e(i,[["render",n]]);export{u as __pageData,m as default};
